"timestamp with time zone","notes":"text","created_at":"timestamp with time zone","section_id":"uuid"},"permissions":["projects"]},"fm_cleaning_visit_items":{"fields":{"id":"uuid","visit_id":"uuid","area_id":"uuid","status":"text","note":"text","sort_order":"integer","created_at":"timestamp with time zone"},"permissions":["projects"]},"fm_daily_cleaning_checks":{"fields":{"id":"uuid","fm_contract_id":"uuid","check_date":"date","area":"text","task_name":"text","status":"text","remarks":"text","checked_by":"text","created_at":"timestamp with time zone","updated_at":"timestamp with time zone"},"permissions":["projects"]},"weekly_reports":{"fields":{"id":"uuid","contract_id":"uuid","reporting_period_id":"uuid","week_start":"date","week_end":"date","report_no":"text","status":"text","ppm_completed":"integer","work_orders_completed":"integer","open_issues":"integer","sla_breaches":"integer","remarks":"text","created_at":"timestamp with time zone","updated_at":"timestamp with time zone","prepared_by":"text","reviewed_by":"text","submitted_at":"timestamp with time zone","approved_at":"timestamp with time zone"},"permissions":["contracts"]},"monthly_reports":{"fields":{"id":"uuid","contract_id":"uuid","reporting_period_id":"uuid","month_start":"date","month_end":"date","report_no":"text","status":"text","ppm_compliance_percent":"numeric","reactive_closure_percent":"numeric","sla_compliance_percent":"numeric","manpower_variance":"numeric","remarks":"text","created_at":"timestamp with time zone","updated_at":"timestamp with time zone","prepared_by":"text","reviewed_by":"text","submitted_at":"timestamp with time zone","approved_at":"timestamp with time zone"},"permissions":["contracts"]},"reporting_periods":{"fields":{"id":"uuid","contract_id":"uuid","period_type":"text","period_start":"date","period_end":"date","label":"text","status":"text","created_at":"timestamp with time zone","updated_at":"timestamp with time zone","remarks":"text"},"permissions":["contracts"]},"invoice_p