 spec jsonb; f jsonb; permission text; col text; typ text; op text; val jsonb;
 tbl text := query_spec->>'table'; mode_name text := query_spec->>'mode'; metric text := query_spec->>'metric';
 predicates text := 'true'; expression text; answer jsonb;
begin
 if auth.uid() is null or jsonb_typeof(query_spec) is distinct from 'object'
 or exists(select 1 from jsonb_object_keys(query_spec) k where k not in ('table','mode','metric','filters'))
 or tbl is null or mode_name is null or not (catalogue ? tbl) or mode_name not in ('sum','outstanding')
 or jsonb_typeof(query_spec->'filters') is distinct from 'array' or jsonb_array_length(query_spec->'filters')>8
 then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
 spec := catalogue->tbl;
 for permission in select jsonb_array_elements_text(spec->'permissions') loop
   if not public.eva_crm_can_read(permission) then raise exception 'crm_denied' using errcode='42501'; end if;
 end loop;
 if mode_name='sum' and not(spec->'fields' ? 'currency')
 and not ((tbl in ('contract_payments','fm_contract_payments') and metric='value')
 or (tbl='invoice_packs' and metric in ('net_payable','vat_amount','total_amount'))) then
   raise exception 'crm_currency_not_defined' using errcode='22023';
 end if;
 if mode_name='sum' then
   if coalesce(spec->'fields'->>metric,'') not in ('numeric','integer','bigint','smallint','double precision','real')
   then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
   if (spec->'fields' ? 'currency') and not exists(
     select 1 from jsonb_array_elements(query_spec->'filters') x
     where x->>'field'='currency' and x->>'op'='eq' and x->>'value' ~ '^[A-Z]{3}$')
   then raise exception 'crm_currency_required' using errcode='22023'; end if;
 elsif tbl not in ('contract_payments','fm_contract_payments') then
   raise exception 'crm_invalid_plan' using errcode='22023';
 end if;
 for f in select value from jsonb_array_elements(query_spec->'filters') loop
   if jsonb_typeof(f) is distinct from 'object' or not(f ?& array['field','op','value'])
   or exists(select 1 from jsonb_object_keys(f) k where k not in ('field','op','value'))
   then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
   col:=f->>'field'; op:=f->>'op'; val:=f->'value'; typ:=spec->'fields'->>col;
   if typ is null or op not in ('eq','neq','lt','lte','gt','gte','is','not_is','contains')
   then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
   if op in ('is','not_is') then
     if val is distinct from 'null'::jsonb then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
     predicates:=predicates||format(' and %I is %s null',col,case when op='not_is' then 'not' else '' end);
   else
     if jsonb_typeof(val) not in ('string','number','boolean') or length(val#>>'{}')>200
     then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
     if typ in ('numeric','integer','bigint','smallint','double precision','real') and jsonb_typeof(val)<>'number'
       or typ='uuid' and (op not in ('eq','neq') or (val#>>'{}') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$')
       or typ='boolean' and (jsonb_typeof(val)<>'boolean' or op not in ('eq','neq'))
       or typ not in ('numeric','integer','bigint','smallint','double precision','real','boolean') and jsonb_typeof(val)<>'string'
     then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
     if op='contains' then
       if typ not in ('text','character varying') then raise exception 'crm_invalid_plan' using errcode='22023'; end if;
       predicates:=predicates||format(' and %I ilike %L',col,'%'||replace(replace(replace(replace(val#>>'{}','*',''),'%',''),'_',''),chr(92),'')||'%');
     else
       predicates:=predicates||format(' and %I %s %L::%s',col,
         case op when 'eq' then '=' when 'neq' then '<>' when 'lt' then '<' when 'lte' then '<=' when 'gt' then '>' when 'gte' then '>=' end,
         val#>>'{}',typ);
     end if;
   end if;
 end loop;
 if mode_name='sum' then
   expression:=format('select jsonb_build_object(''table'',%L,''mode'',''sum'',''metric'',%L,''total'',count(*),''sum'',round(coalesce(sum(%I::numeric),0),2),''snapshot'',true) from public.%I where %s',tbl,metric,metric,tbl,predicates);
 else
   expression:=format($q$
     with rows as (
       select value,case when received_date is not null then 'Received'
       when payment_date is null or payment_date >= (now() at time zone 'Asia/Dubai')::date then 'Not Yet Due'
       when (now() at time zone 'Asia/Dubai')::date - payment_date <= 15 then 'Due' else 'Overdue' end as category
       from public.%I where %s
     ) select jsonb_build_object('table',%L,'mode','outstanding','total',count(*),'snapshot',true,
       'asOf',to_char(now() at time zone 'Asia/Dubai','YYYY-MM-DD'),
       'outstandingCount',count(*) filter(where category in ('Due','Overdue')),
       'paymentCounts',jsonb_build_object('Received',count(*) filter(where category='Received'),'Not Yet Due',count(*) filter(where category='Not Yet Due'),'Due',count(*) filter(where category='Due'),'Overdue',count(*) filter(where category='Overdue')),
       'paymentTotals',jsonb_build_object(
         'Received',round(coalesce(sum(value) filter(where category='Received'),0),2),
         'Not Yet Due',round(coalesce(sum(value) filter(where category='Not Yet Due'),0),2),
         'Due',round(coalesce(sum(value) filter(where category='Due'),0),2),
         'Overdue',round(coalesce(sum(value) filter(where category='Overdue'),0),2)),
       'outstanding',round(coalesce(sum(value) filter(where category in ('Due','Overdue')),0),2)) from rows
     $q$,tbl,predicates,tbl);
 end if;
 execute expression into answer;
 answer:=answer||jsonb_build_object('currency',case when spec->'fields' ? 'currency' then (select x->>'value' from jsonb_array_elements(query_spec->'filters') x where x->>'field'='currency' and x->>'op'='eq' limit 1) else 'AED' end);
 return answer;
end;
$rpc$;
revoke all on function public.eva_crm_aggregate(jsonb) from public, anon;
grant execute on function public.eva_crm_aggregate(jsonb) to authenticated;
comment on function public.eva_crm_aggregate(jsonb) is 'Caller-bound allowlisted read-only totals. No user SQL. Single statement snapshot; existing RLS and module permissions enforced.';
